    name: o.name,
    type: o.type,
    subType: o.subType,
    source: o.source,
    var: o.var,
    body: o.body,
    custom: o.custom === "true" || o.custom === true,
    target: o.target,
  });

  uipath.context = (actEl.context?.input ?? []).map(mapInput);
